def check(zone, hour, minute, years=range(2024, 2028)):
    z = ZoneInfo(zone)
    problems = []
    for y in years:
        start = datetime(y, 1, 1, 0, 0, tzinfo=z)
        end = datetime(y + 1, 1, 1, 0, 0, tzinfo=z)
        runs = runs_between(start, end, hour, minute, zone)
        prev_utc = None
        for r in runs:
            loc = r.astimezone(z)
            if (loc.hour, loc.minute, loc.second, loc.microsecond) != (hour, minute, 0, 0):
                problems.append(f"  {zone} {y}: run at local {loc} (utc {r.astimezone(UTC)}) not at {hour}:{minute:02d}")
            if prev_utc is not None and r.astimezone(UTC) <= prev_utc:
                problems.append(f"  {zone} {y}: runs not strictly increasing at {r}")
            prev_utc = r.astimezone(UTC)
        # each consecutive run must equal next_daily_run(prev run)
        for a, b in zip(runs, runs[1:]):
            n = next_daily_run(a, hour, minute, zone)
            if n != b:
                problems.append(f"  {zone} {y}: next_daily_run({a}) == {n} but sequence has {b}")
    return problems

